local Players = game:GetService("Players") local UserInputService = game:GetService("UserInputService") local player = Players.LocalPlayer local gui = player:WaitForChild("PlayerGui") local rebirthGui = gui:WaitForChild("RebirthPanel") local panel = rebirthGui.PanelFit.Panel local freeButton = panel.Rebirth local gradient = freeButton.UIGradient local openButton = gui.Hud.Tiles.Rebirth local levelLabel = gui.Hud.StatStack.LevelBar.Left local CHECK_INTERVAL = 0.25 local PANEL_DELAY = 0.5 local CONFIRM_TIME = 1 local RETRY_DELAY = 5 local BASE_REBIRTH = 572 local BASE_LEVEL = 8600 local LEVEL_INCREMENT = 15 local READY = { R = 0.517647, G = 1, B = 0.0627451 } local MAIN_WIDTH = 250 local MAIN_HEIGHT = 120 local SYMBOL_SIZE = 42 local MIN_MAIN_WIDTH = 220 local MAX_MAIN_WIDTH = 450 local MIN_MAIN_HEIGHT = 110 local MAX_MAIN_HEIGHT = 320 local MIN_SYMBOL_SIZE = 32 local MAX_SYMBOL_SIZE = 85 local autoEnabled = true local busy = false local lastAttempt = 0 local oldUI = gui:FindFirstChild("FreeRebirthControlV9") if oldUI then oldUI:Destroy() end local screen = Instance.new("ScreenGui") screen.Name = "FreeRebirthControlV9" screen.ResetOnSpawn = false screen.IgnoreGuiInset = true screen.DisplayOrder = 99999 screen.Parent = gui local frame = Instance.new("Frame") frame.Name = "Main" frame.Size = UDim2.fromOffset(MAIN_WIDTH, MAIN_HEIGHT) frame.Position = UDim2.new(0, 25, 0.45, 0) frame.BackgroundColor3 = Color3.fromRGB(27, 33, 43) frame.BorderSizePixel = 0 frame.Active = true frame.Parent = screen local corner = Instance.new("UICorner") corner.CornerRadius = UDim.new(0, 10) corner.Parent = frame local stroke = Instance.new("UIStroke") stroke.Color = Color3.fromRGB(75, 91, 110) stroke.Thickness = 1.3 stroke.Parent = frame local header = Instance.new("TextButton") header.Name = "DragHandle" header.Size = UDim2.new(1, -42, 0, 34) header.Position = UDim2.fromOffset(0, 0) header.BackgroundColor3 = Color3.fromRGB(42, 54, 69) header.BorderSizePixel = 0 header.Text = "  AUTO FREE RE