ze.TextColor3 = Color3.new(1, 1, 1) mainResize.TextSize = 12 mainResize.Parent = frame local mainResizeCorner = Instance.new("UICorner") mainResizeCorner.CornerRadius = UDim.new(0, 4) mainResizeCorner.Parent = mainResize local miniButton = Instance.new("TextButton") miniButton.Name = "MiniSymbol" miniButton.Size = UDim2.fromOffset(SYMBOL_SIZE, SYMBOL_SIZE) miniButton.Position = frame.Position miniButton.BackgroundColor3 = Color3.fromRGB(27, 33, 43) miniButton.BorderSizePixel = 0 miniButton.Text = "☯" miniButton.TextColor3 = Color3.new(1, 1, 1) miniButton.Font = Enum.Font.GothamBold miniButton.TextSize = 25 miniButton.Visible = false miniButton.ClipsDescendants = true miniButton.Parent = screen local miniCorner = Instance.new("UICorner") miniCorner.CornerRadius = UDim.new(1, 0) miniCorner.Parent = miniButton local miniStroke = Instance.new("UIStroke") miniStroke.Color = Color3.fromRGB(100, 125, 150) miniStroke.Thickness = 1.5 miniStroke.Parent = miniButton local miniResize = Instance.new("TextButton") miniResize.Name = "ResizeSymbol" miniResize.Size = UDim2.fromOffset(12, 12) miniResize.AnchorPoint = Vector2.new(0.5, 0.5) miniResize.BackgroundColor3 = Color3.fromRGB(85, 105, 130) miniResize.BorderSizePixel = 0 miniResize.Text = "↘" miniResize.TextColor3 = Color3.new(1, 1, 1) miniResize.TextSize = 8 miniResize.Visible = false miniResize.Parent = screen local miniResizeCorner = Instance.new("UICorner") miniResizeCorner.CornerRadius = UDim.new(1, 0) miniResizeCorner.Parent = miniResize local function updateMiniGrip() miniResize.Position = UDim2.fromOffset( miniButton.AbsolutePosition.X + SYMBOL_SIZE - 1, miniButton.AbsolutePosition.Y + SYMBOL_SIZE - 1 ) end local function updateUI(message) if autoEnabled then toggle.Text = "AUTO: ON  |  CLICK TO STOP" toggle.BackgroundColor3 = Color3.fromRGB(30, 155, 85) else toggle.Text = "AUTO: OFF  |  CLICK TO START" toggle.BackgroundColor3 = Color3.fromRGB(190, 65, 65) end if message then status.Text = message elseif autoEnabled then status.Text = "Monitoring level..." else status.Text = "Automation stopped." end end toggle.Activated:Connect(function() autoEnabled = not autoEnabled updateUI() end) updateUI() minimizeButton.Activated:Connect(function() frame.Visible = false miniButton.Position = UDim2.fromOffset( frame.AbsolutePosition.X, frame.AbsolutePosition.Y ) miniButton.Visible = true miniResize.Visible = true updateMiniGrip() end) local miniMoved = false miniButton.Activated:Connect(function() if miniMoved then miniMoved = false return end frame.Position = miniButton.Position frame.Visible = true miniButton.Visible = false miniResize.Visible = false end) local interaction = nil local function startInteraction(mode, object, input) if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then interaction = { mode = mode, object = object, input = input, startPosition = input.Position, startUDimPosition = object.Position, startSize = object.AbsoluteSize } end end header.InputBegan:Connect(function(input) startInteraction("moveMain", frame, input) end) mainResize.InputBegan:Connect(function(input) startInteraction("resizeMain", frame, input) end) miniButton.InputBegan:Connect(function(input) miniMoved = false startInteraction("moveMini", miniButton, input) end) miniResize.InputBegan:Connect(function(input) startInteraction("resizeMini", miniButton, input) end) UserInputService.InputChanged:Connect(function(input) if not interaction then return end if input.UserInputType ~= Enum.UserInputType.MouseMovement and input.UserInputType ~= Enum.UserInputType.Touch then return end local delta = input.Position - interaction.startPosition local mode = interaction.mode local object = interaction.object if mode == "moveMain" or mode == "moveMini" then object.Position = UDim2.new( interaction.startUDimPosition.X.Scale, interaction.startUDimPosition.X.Offset + delta.X, interaction.startUDimPosition.Y.Scale, interaction.startUDimPosition.Y.Offset + delta.Y ) if mode == "moveMini" then if math.abs(delta.X) + math.abs(delta.Y) > 5 then miniMoved = true end updateMiniGrip() end elseif mode == "resizeMain" then local newWidth = math.clamp( interaction.startSize.X + delta.X, MIN_MAIN_WIDTH, MAX_MAIN_WIDTH ) local newHeight = math.clamp( interaction.startSize.Y + delta.Y, MIN_MAIN_HEIGHT, MAX_MAIN_HEIGHT ) frame.Size = UDim2.fromOffset(newWidth, newHeight) elseif mode == "resizeMini" then local change = math.max(delta.X, delta.Y) SYMBOL_SIZE = math.clamp( interaction.startSize.X + change, MIN_SYMBOL_SIZE, MAX_SYMBOL_SIZE ) miniButton.Size = UDim2.fromOffset( SYMBOL_SIZE, SYMBOL_SIZE ) miniButton.TextSize = math.floor(SYMBOL_SIZE * 0.55) updateMiniGrip() end end) UserInputService.InputEnded:Connect(function(input) if interaction then if input.UserInputType == Enum.UserInputType.MouseButton1 or (input.UserInputType == Enum.UserInputType.Touch and input == interaction.input) then interaction = nil updateMiniGrip() end end end) local function getLevel() return tonumber(levelLabel.Text:match("%d+")) end local function getRebirthCount() local value = player:GetAttribute("Rebirths") if typeof(value) == "number" then return value end return nil end local function getRequiredLevel(rebirths) return BASE_LEVEL + LEVEL_INCREMENT * (rebirths - BASE_REBIRTH) end local function isReady() local color = gradient.Color.Keypoints[1].Value return math.abs(color.R - READY.R) < 0.015 and math.abs(color.G - READY.G) < 0.015 and math.abs(color.B - READY.B) < 0.015 end local function openPanel() if not rebirthGui.Enabled then firesignal(openButton.Activated) task.wait(PANEL_DELAY) end end local function closePanel() if rebirthGui.Enabled then firesignal(openButton.Activated) end end task.spawn(function() while screen.Parent and player.Parent do task.wait(CHECK_INTERVAL) if autoEnabled and not busy then local level = getLevel() local rebirths = getRebirthCount() if level and rebirths then local target = getRequiredLevel(rebirths) if level >= target and os.clock() - lastAttempt >= RETRY_DELAY then busy = true lastAttempt = os.clock() local wasOpen = rebirthGui.Enabled local beforeCount = getRebirthCount() updateUI("Target reached...") local success = pcall(function() if not wasOpen then openPanel() end if not autoEnabled then return end if rebirthGui.Enabled and freeButton.Visible and freeButton.Active and freeButton.Interactable and isReady() then updateUI("Activating free rebirth...") firesignal(freeButton.Activated) local confirmed = false for i = 1, 4 do task.wait(CONFIRM_TIME / 4) local afterCount = getRebirthCount() if beforeCount and afterCount and afterCount > beforeCount then updateUI("Rebirth confirmed!") confirmed = true break end end if not confirmed then updateUI("Confirmation not detected.") end else updateUI("Waiting for readiness...") end end) if not wasOpen and rebirthGui.Enabled then closePanel() end if not success then updateUI("Error occurred.") end busy = false end end end end end)
